    // [WSCoop] Per-player loot: the looter's own game plays the opening; the server keeps the chest
    // closed for everyone else.
    void WSCoopPlayLocalOpen()
    {
        ProxyMesh.StaticMesh = OpenedMesh;
        ChestEffect.Deactivate();
        if (AnimInstance != nullptr)
        {
            AnimInstance.SetOpen(true);
        }
    }

    // [WSCoop] Per-player loot: hides the chest on this machine only.
    void WSCoopSetLocallyHidden(const bool bHide)
    {
        Root.SetVisibility(!bHide, true);
        if (!System::IsServer())
        {
            SetActorEnableCollision(!bHide); // no interaction prompt (the listen-server host keeps it for others)
        }
        if (bHide)
        {
            ChestEffect.Deactivate();
        }
        else if (!bIsOpen)
        {
            ProxyMesh.StaticMesh = ClosedMesh;
            ChestEffect.Activate();
